{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Pethidine, a small ionizable drug with moderate first-pass metabolism, has an absolute oral bioavailability of 0.61 in healthy volunteers, supporting that small molecules with similar size and polar functionality can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Maraviroc, despite substantial first-pass metabolism and transporter involvement, has an absolute oral bioavailability of 23.1%, establishing that even drugs with incomplete absorption and metabolism clear the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "4-Phenylbutyric acid, a small aromatic carboxylic acid, has an absolute oral bioavailability of 78%, directly supporting high F for a carboxylic-acid-containing molecule like the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Pidotimod, a small zwitterionic thiazolidine carboxylic acid with an amide, has an oral bioavailability of 42-44%, supporting high F for the query's proline-carboxylic acid/amide framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ampicillin, a zwitterionic amino-acid-like drug with incomplete absorption, still achieves 62 ± 17% oral bioavailability, indicating that the query's ionizable amino-acid character is compatible with F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query, a phenylthio-substituted proline thiol resembling zofenoprilat, is best predicted as having high oral bioavailability. Direct measurements in relevant small molecules—aromatic carboxylic acids, zwitterionic amino-acid drugs, and small polar drugs—consistently exceed 20%, often by a wide margin. The only sub-20% record involves perindoprilat formation from a prodrug rather than direct oral bioavailability of the diacid, so it does not outweigh the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for zofenoprilat itself.",
    "Perindoprilat records reflect systemic availability after oral prodrug administration, not direct oral dosing of the diacid.",
    "Potential effects of free thiol oxidation/stability and food on zofenoprilat absorption are not captured by the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

